PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,source_type TEXT NOT NULL,region TEXT NOT NULL,trust_priority INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,license_status TEXT NOT NULL,last_updated TEXT);
CREATE TABLE IF NOT EXISTS classes(id TEXT PRIMARY KEY,name_ru TEXT NOT NULL,name_en TEXT NOT NULL,role_ru TEXT,weapon_ru TEXT,damage_type_ru TEXT,mechanics_ru TEXT,strengths_ru TEXT,weaknesses_ru TEXT,pve_role_ru TEXT,solo_pvp_role_ru TEXT,small_scale_role_ru TEXT,group_pvp_role_ru TEXT,source_id TEXT REFERENCES sources(id),region TEXT NOT NULL,patch TEXT NOT NULL,confidence TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY,external_id TEXT UNIQUE,name_ru TEXT NOT NULL,name_en TEXT NOT NULL,aliases TEXT NOT NULL DEFAULT '',type TEXT NOT NULL,subtype TEXT,grade TEXT,item_level INTEGER,required_level INTEGER,class_id TEXT REFERENCES classes(id),description_ru TEXT,source_region TEXT NOT NULL,source_version TEXT,localization_status TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE IF NOT EXISTS item_stats(item_id INTEGER NOT NULL REFERENCES items(id),stat_id TEXT NOT NULL,value REAL NOT NULL,PRIMARY KEY(item_id,stat_id));
CREATE TABLE IF NOT EXISTS skills(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,class_id TEXT NOT NULL REFERENCES classes(id),name_ru TEXT NOT NULL,name_en TEXT NOT NULL,aliases TEXT NOT NULL DEFAULT '',description_ru TEXT,max_level INTEGER,source_id TEXT REFERENCES sources(id),region TEXT NOT NULL,patch TEXT NOT NULL,confidence TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS instances(id INTEGER PRIMARY KEY,name_ru TEXT NOT NULL,name_en TEXT NOT NULL,aliases TEXT NOT NULL DEFAULT '',category TEXT,stars INTEGER,min_level INTEGER,min_gear_score_global INTEGER,min_gear_score_tw INTEGER,party_size INTEGER,description TEXT,source_status TEXT NOT NULL DEFAULT 'unverified');
CREATE TABLE IF NOT EXISTS bosses(id INTEGER PRIMARY KEY,instance_id INTEGER REFERENCES instances(id),name_ru TEXT NOT NULL,name_en TEXT NOT NULL,aliases TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS drops(boss_id INTEGER NOT NULL REFERENCES bosses(id),item_id INTEGER NOT NULL REFERENCES items(id),drop_rate REAL,reward_type TEXT,PRIMARY KEY(boss_id,item_id));
CREATE TABLE IF NOT EXISTS systems(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name_ru TEXT NOT NULL,name_en TEXT NOT NULL,description TEXT,risk_level TEXT NOT NULL,stop_rule TEXT);
CREATE TABLE IF NOT EXISTS roadmap_steps(id INTEGER PRIMARY KEY,region TEXT NOT NULL,min_gs INTEGER NOT NULL,max_gs INTEGER NOT NULL,order_index INTEGER NOT NULL,title_ru TEXT NOT NULL,description_ru TEXT NOT NULL,priority TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roadmap_actions(id INTEGER PRIMARY KEY,roadmap_step_id INTEGER NOT NULL REFERENCES roadmap_steps(id),action_type TEXT NOT NULL,target_id TEXT NOT NULL,title_ru TEXT NOT NULL,priority TEXT NOT NULL,explanation TEXT NOT NULL,source_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activities(id INTEGER PRIMARY KEY,name_ru TEXT NOT NULL,cadence TEXT NOT NULL,weekly_limit INTEGER,daily_limit INTEGER,reward TEXT,reason TEXT,priority TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS class_builds(id TEXT PRIMARY KEY,class_id TEXT NOT NULL REFERENCES classes(id),name_ru TEXT NOT NULL,name_en TEXT NOT NULL,mode TEXT NOT NULL,stage TEXT NOT NULL,concept_ru TEXT NOT NULL,rotation_ru TEXT,opener_ru TEXT,defensive_ru TEXT,alternatives_ru TEXT,mistakes_ru TEXT,region TEXT NOT NULL,patch TEXT NOT NULL,game_version TEXT,source_version TEXT,confidence TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS build_components(id INTEGER PRIMARY KEY,build_id TEXT NOT NULL REFERENCES class_builds(id),component_type TEXT NOT NULL,target_id TEXT NOT NULL,label_ru TEXT NOT NULL,weight REAL NOT NULL,required INTEGER NOT NULL DEFAULT 1,stage TEXT NOT NULL,acquisition_ru TEXT,reason_ru TEXT,priority TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stat_priorities(id INTEGER PRIMARY KEY,build_id TEXT NOT NULL REFERENCES class_builds(id),stat_slug TEXT NOT NULL,name_ru TEXT NOT NULL,order_index INTEGER NOT NULL,explanation_ru TEXT NOT NULL,breakpoint TEXT,confirmed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS skill_breakpoints(id INTEGER PRIMARY KEY,skill_id INTEGER NOT NULL REFERENCES skills(id),build_id TEXT REFERENCES class_builds(id),stage TEXT NOT NULL,target_level INTEGER,priority TEXT NOT NULL,reason_ru TEXT NOT NULL,confirmed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS recommendation_rules(id TEXT PRIMARY KEY,class_id TEXT REFERENCES classes(id),build_id TEXT REFERENCES class_builds(id),conditions_json TEXT NOT NULL,recommendation_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,region TEXT NOT NULL,patch TEXT NOT NULL,confidence TEXT NOT NULL,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS provider_versions(provider_id TEXT PRIMARY KEY REFERENCES sources(id),etag TEXT,last_modified TEXT,content_hash TEXT,source_version TEXT,last_checked TEXT,last_success TEXT,status TEXT NOT NULL DEFAULT 'disabled',error TEXT,record_count INTEGER NOT NULL DEFAULT 0);
CREATE VIRTUAL TABLE IF NOT EXISTS search_index USING fts5(entity_type UNINDEXED,entity_id UNINDEXED,name_ru,name_en,aliases,details,tokenize='unicode61 remove_diacritics 2');
